<template>
  <div id="qa-tree-container" class="qa-tree-container">
    <nodes-preview :node-list="nodeList" />
    <canvas-zoom :graph="xGraph" />
    <div id="qa-tree-g6" ref="painter"></div>
    <div class="layout-button">
      <!-- <button class="button" @click="toggleEdgeType">🎡</button> -->
      <button class="button" @click="centerGraph">🔲</button>
      <button class="button" @click="handleClickLayout(true)">🗂️</button>
      <button class="button" @click="handlerSave">🗄️</button>
    </div>
  </div>
</template>

<script>
import _ from "lodash";
import G6 from "@antv/g6";
import { getEdgeDefineCfg } from "./edge/edge.js";
// import { GraphLayoutPredict } from "@antv/vis-predict-engine";
import { getCustomNodeCfg } from "./node/customNode.js";
import { getStartNodeCfg } from "./node/startNode.js";

import NodesPreview from "./html-components/nodes-preview/index.vue";
import CanvasZoom from "./html-components/canvas-zoom/index.vue";
import {
  getDragCreateEdgeOpt,
  buttonClick,
  getClickCreateEdgeOpt,
  getDragCreateNodeOpt,
  nodeClick,
  getDeleteEdgeOpt,
} from "./behavior/index.js";
import { validateTree } from "./utils/treeValidation";
// DESC: shallowRef 非常重要，因为 g6 无法共享 proxy 构造出来的数据
import { shallowRef } from "vue";
import { g6Config } from "./config.ts";
import { getNodeUUID } from "@/utils";

export default {
  name: "QaTree",

  components: {
    NodesPreview,
    CanvasZoom,
  },

  // mixins: [mixins],
  props: {
    gConfig: {
      type: Object,
      default: () => ({}),
    },
    qaTreeDisabled: {
      type: Boolean,
      default: false,
    },
    initJson: {
      type: String,
      default: "",
    },
  },
  graphNodes: [],
  graphEdges: [],
  setup() {
    const xGraph = shallowRef(null);
    return { xGraph: xGraph };
  },
  data() {
    return {};
  },

  computed: {
    resizeDebounce() {
      return _.debounce(() => {
        this.resizePainter();
      }, 100);
    },
    baseDrawDataObj() {
      return JSON.parse(this.initJson);
    },
    centerGraph() {
      // 延迟至少 650ms 给其他动画一些时间
      return _.debounce(this._centerGraph, 650);
    },
    nodeList() {
      return this.gConfig?.node?.nodeList ?? [];
    },
    startNodeType() {
      return this.gConfig?.node?.startNodeType ?? "START";
    },
  },
  watch: {
    // 启用停用
    qaTreeDisabled(value) {
      this.xGraph.setMode(value ? "custom" : "default");
    },
  },

  mounted() {
    this.init();
  },

  beforeUnmount() {
    console.log("beforeUnmount1");
    window.removeEventListener("resize", this.resizeDebounce);
    this.xGraph.destroy();
  },

  methods: {
    async init() {
      this.registerItems();
      this.registerBehavior();
      this.initGraph();
      this.registerEvent(this.xGraph);
      window.addEventListener("resize", this.resizeDebounce);
      this.draw();
      this.centerGraph();
    },
    async handlerSave() {
      console.log(this.xGraph.save());
      return this.xGraph.save();
    },
    async organizeLayout(isManual) {
      // const chatData = this.xGraph.save();
      // const { predictLayout, confidence } = await GraphLayoutPredict.predict(
      //   chatData
      // );
      const predictLayout = "force";
      const confidence = "100%";
      console.log(predictLayout, confidence);
      if (isManual) {
        this.xGraph.updateLayout({
          layout: {
            type: predictLayout,
          },
          nodesFilter: (node) => {
            // console.log(node);
            // TODO: 不整理那些无法到达 startNode 的点
            return true;
            // return this.startRootNodeIds.has(node.id);
          },
        });
      } else {
        this.xGraph.updateLayout({
          layout: {
            type: predictLayout,
          },
          nodesFilter: (node) => {
            // console.log(node);
            // TODO: 不整理那些无法到达 startNode 的点
            return true;
            // return this.startRootNodeIds.has(node.id);
          },
        });
      }
    },
    async handleClickLayout(isManual) {
      // 手动整理时才整理离散节点
      await this.organizeLayout(isManual);
      // 等上一个动画结束执行该动画
      this.centerGraph();
    },
    // 将图内容移动到中央位置
    _centerGraph() {
      this.xGraph.fitCenter(true, {
        duration: 500, // Number，一次动画的时长
        easing: "easeQuadInOut", // String，动画函数
      });
    },
    draw() {
      this.initData();
      this.xGraph.read({
        nodes: _.cloneDeep(this.graphNodes),
        edges: _.cloneDeep(this.graphEdges),
      });
    },

    initData() {
      this.initNodes();
      this.initEdges();
    },

    initNodes() {
      // 如果是空画布, 新增开始节点
      const nodes = this.baseDrawDataObj.nodes;
      this.graphNodes = nodes;
      if (this.graphNodes.length === 0) {
        const nodeType = this.startNodeType;
        const nodeOpt = this.nodeList.find((node) => node.type === nodeType);
        const nodeName = `${nodeOpt.name}${1}`;
        this.graphNodes = [
          {
            id: getNodeUUID(),
            type: "start-node",
            x: 0,
            y: 0,
            label: nodeName,
            nodeData: {
              nodeData: {},
              nodeName,
              nodeType,
            },
          },
        ];
      }
    },
    initEdges() {
      const edges = this.baseDrawDataObj.edges;
      this.graphEdges = edges;
    },
    registerItems() {
      const edgeTypes = [
        { name: "line" },
        { name: "polyline" },
        { name: "arc" },
        { name: "quadratic" },
        { name: "cubic" },
        { name: "cubic-vertical" },
        { name: "cubic-horizontal" },
        { name: "loop" },
      ];
      edgeTypes.forEach((opt) => {
        const { name } = opt;
        const config = getEdgeDefineCfg(name);

        G6.registerEdge(
          "custom:" + name,
          config.edgeDefinition,
          config.extendShapeType
        );
      });
      console.log(this.gConfig);

      const styleMaps = _.chain(this.nodeList)
        .map((v) => {
          return [v.type, v.styles];
        })
        .fromPairs()
        .value();

      G6.registerNode(
        "custom-node",
        getCustomNodeCfg({
          styleMaps,
        }),
        "rect"
      );

      G6.registerNode("start-node", getStartNodeCfg({ styleMaps }), "rect");
    },

    registerBehavior() {
      G6.registerBehavior(
        "delete-edge",
        getDeleteEdgeOpt({
          cfg: this.gConfig.edge.deleteEdgeBehavior,
        })
      );

      // node 的点击事件
      G6.registerBehavior("node-click", nodeClick);

      // 按钮的点击事件
      G6.registerBehavior("node-button-click", buttonClick);

      // 拖拽左侧 DOM 生成新 node
      G6.registerBehavior(
        "drag-create-node",
        getDragCreateNodeOpt({
          startNodeType: this.startNodeType,
          nodeList: this.nodeList,
        })
      );

      // 拖拽 node 末尾圆点生成 edge
      G6.registerBehavior(
        "drag-create-edge",
        getDragCreateEdgeOpt(this.gConfig.edge.createEdgeBehavior)
      );

      // 点击 node 末尾圆点生成 edge
      G6.registerBehavior(
        "click-create-edge",
        getClickCreateEdgeOpt(this.gConfig.edge.createEdgeBehavior)
      );
    },
    registerEvent(graph) {
      // 初次渲染
      graph.on("afterrender", () => {
        console.log("afterrender11");

        setTimeout(() => {
          try {
            const findNode = this.xGraph.find("node", (node) => {
              return node.get("type") === "start-node";
            });
            if (findNode) {
              this.xGraph.focusItem(findNode, true);
            }
            // TODO: 查下这个设置有什么用
            // 查过了，没什么用，用来设置刷新策略，默认就是 true
            // https://github.com/antvis/G6/issues/2193
            // 实际上，所有的残留，都是自己设置错误导致的。
            // this.xGraph.get("canvas").set("localRefresh", true);
          } catch (error) {}
        }, 40);
      });

      graph.on("edge:mouseenter", ({ item }) => {
        // console.log("edge:mouseenter");
        graph.setItemState(item, "active", true);
      });
      graph.on("edge:mouseleave", ({ item }) => {
        graph.setItemState(item, "active", false);
      });
      graph.on("node:mouseenter", ({ item }) => {
        // active 表示 hover 状态
        graph.setItemState(item, "active", true);
      });
      graph.on("node:mouseleave", ({ item }) => {
        // active 表示 hover 状态
        graph.setItemState(item, "active", false);
      });

      // item click事件
      graph.on("edge:click", ({ item, target, propagationPath }) => {
        console.log("edge:click", target, propagationPath);
        // 点击 edge 把它设置到顶部
        // item && this.setItemSelected(item);
      });

      graph.on("clickEdge", ({ item }) => {
        console.log("点击连线");

        const edgeModel = item.getModel();
        this.$emit("edgeClick", edgeModel.id, edgeModel.source);
      });

      graph.on("clickNode", (ev) => {
        // console.log("点击节点", item);
        // console.log(item.getModel());
        // this.highLightNodeEdges(ev);
        // this.highLightNodePathEdges(ev);
      });

      graph.on("node:buttonClick", (ev) => {
        console.log("点击节点上按钮", ev);

        const { target, item } = ev;
        const targetName = target.get("name") || "";
        const buttonType = /button:(.+)/.exec(targetName)[1];
        console.log(buttonType);
        if (buttonType === "delete") {
          // 删除节点，要把节点的上下边都给删除
          this.deleteNode(ev);
        }
        if (buttonType === "copy") {
          this.copyNode(ev);
        }
      });

      graph.on("edge:afterUpdate", this.afterUpdateEdge);

      // 新增和删除元素，进行校验
      graph.on("afteradditem", () => {}); // 加边另外有回调
      graph.on("afterremoveitem", ({ item: { id, source } }) => {
        console.log("afterremoveitem");
        validateTree(this.nodes);
      });

      graph.on("dragCreateNode", (params) => {
        console.log(params);
        this.createNode(params.nodeType, params.position, params.data);
      });

      // graph.on("canvas:click", (e) => {
      //   if (!e.item) {
      //     // 清空高亮元素
      //     this.cancelHighLightAllEdges();
      //   }
      // });
    },
    initGraph() {
      const qaTreeG6Dom = document.getElementById("qa-tree-g6");
      const painterHeight = parseInt(getComputedStyle(qaTreeG6Dom).height);
      const painterWidth = parseInt(getComputedStyle(qaTreeG6Dom).width);
      const plugins = [
        (() => {
          const minimapOpt = this.gConfig.minimap;
          if (minimapOpt === true) {
            return new G6.Minimap({
              container: "minimap",
              className: "minimap",
              type: "keyShape",
              size: [263, 136],
            });
          }
          if (minimapOpt) {
            return new G6.Minimap({
              container: "minimap",
              className: "minimap",
              ...minimapOpt,
            });
          }
        })(),
        (() => {
          const oldOnMenuShow = G6.Menu.prototype.onMenuShow;
          G6.Menu.prototype.onMenuShow = function (evt) {
            const newOnMenuShow = oldOnMenuShow.bind(this);
            if (evt?.item?.destroyed) {
              this.onMenuHide();
              return;
            } else {
              return newOnMenuShow(evt);
            }
          };

          return new G6.Menu({
            offsetX: 6,
            offsetY: 10,
            itemTypes: ["edge"],
            trigger: "click",
            getContent(e) {
              const outDiv = document.createElement("div");
              outDiv.style.width = "180px";
              outDiv.innerHTML = `<ul>
        <li data-edge-type="01">01</li>
        <li data-edge-type="02">02</li>
        <li data-edge-type="03">03</li>
        <li data-edge-type="04">04</li>
        <li data-edge-type="05">05</li>
      </ul>`;
              return outDiv;
            },
            handleMenuClick(target, item) {
              console.log(target, item);
              // TODO: 拿到 edge 的 target 的类型，和配置
              const edgeType = target.getAttribute("data-edge-type");
              if (!item.destroyed && edgeType) {
                item.update({
                  label: edgeType + " ▼",
                });
              }
            },
            shouldBegin(evt) {
              console.log(evt);
              const target = evt.target;
              console.log(target);
              if (!evt.item.destroyed) {
                if (
                  target.get("name") === "text-shape" &&
                  target.get("className") === "edge-label"
                ) {
                  return true;
                }

                if (target.get("name") === "text-bg-shape") {
                  return true;
                }
              }
            },
          });
        })(),
      ].filter((v) => v);

      console.log(plugins);
      const cfg = _.merge(
        {},
        g6Config,
        {
          container: "qa-tree-g6",
          width: painterWidth,
          defaultEdge: {
            type: "custom:" + g6Config.defaultEdge.type,
          },
          height: painterHeight,
          plugins,
        },
        this.gConfig.g6Config
      );

      console.log(cfg);
      this.xGraph = new G6.Graph(cfg);
      // 初始化数量
      this.xGraph.nodeNum = {};
    },
    async resizePainter() {
      const painterHeight = parseInt(
        getComputedStyle(this.$refs.painter).height
      );
      const painterWidth = parseInt(getComputedStyle(this.$refs.painter).width);
      this.xGraph.changeSize(painterWidth, painterHeight);
      this.xGraph.zoomTo(1, false, false);
      // 给上面动画一些时间
      await new Promise((resolve) => {
        setTimeout(() => {
          resolve(1);
        }, 650);
      });
      this.centerGraph();
    },

    // edge 的终点更新
    afterUpdateEdge({ item }) {
      // 拿到 edge 的 起点，开始验证它有几条 edge
      const edgeSource = item.getSource();
      const sourceOutEdges = edgeSource.getOutEdges();
      // TODO: 根据 source 类型判断是否可链接多条线
      // console.log(item, model);
      console.log(edgeSource.getModel().type);

      const MaxEdgeMaps = {
        "start-node": 1,
      };

      const maxN = MaxEdgeMaps[edgeSource.getModel().type] || 4;
      if (sourceOutEdges.length > maxN) {
        sourceOutEdges
          // 抛开自己不谈
          .filter((v) => v !== item)
          // 再抛开剩下的 n -1 个
          .reverse()
          .slice(maxN - 1)
          .forEach((edge) => {
            this.xGraph.removeItem(edge);
          });
      }
      // validateTree(this.nodes);

      // 添加连线后整理画布
      // this.handleClickLayout();
    },

    deleteNode(ev) {
      const { item } = ev;
      const edges = item.getEdges();
      edges.forEach((edge) => {
        this.xGraph.removeItem(edge);
      });
      this.xGraph.removeItem(item);
    },
    async copyNode(ev) {
      const { item } = ev;
      const model = item.getModel();
      const r = 150;
      const angle = [-60, 60];
      const arc = _.random(
        _.toInteger(-angle[0] * Math.PI),
        _.toInteger(-angle[1] * Math.PI)
      );
      const dx = r * Math.cos(arc / 180);
      const dy = r * Math.sin(arc / 180);
      await Promise.resolve(1);
      this.createNode(
        model.nodeData.nodeType,
        {
          x: model.x + dx,
          y: model.y + dy,
        },
        model.nodeData.data
      );
    },

    createNode(nodeType, position, data) {
      const num =
        this.xGraph.findAll("node", (node) => {
          return _.get(node.getModel(), "nodeData.nodeType") === nodeType;
        })?.length ?? 0;
      const nodeOpt = this.nodeList.find((node) => node.type === nodeType);

      const nodeName = `${nodeOpt.name}${num + 1}`;
      const node = this.xGraph.addItem("node", {
        id: getNodeUUID(),
        type: nodeType === this.startNodeType ? "start-node" : "custom-node",
        x: position.x,
        y: position.y,
        label: nodeName,
        nodeData: {
          nodeName,
          nodeType,
          data,
        },
      });
      node.toFront();
    },

    highLightNodeEdges({ item }) {
      this.cancelHighLightAllEdges();

      const edges = item.getEdges();
      edges.forEach((edge) => this.xGraph.setItemState(edge, "running", true));
    },
    cancelHighLightAllEdges() {
      this.xGraph.stopAnimate();
      const edges = this.xGraph.getEdges();
      edges.forEach((edge) => this.xGraph.setItemState(edge, "running", false));
    },
    highLightNodePathEdges({ item }) {
      this.cancelHighLightAllEdges();
      let allEdges = [];
      let allNodes = [];
      let nodes = [item];
      let edgesArr = [];
      for (let i = 0; i < 20; i++) {
        for (let node of nodes) {
          // if (allNodes.includes(node)) continue;
          allNodes.push(node);
          const cEdges = node.getInEdges();
          edgesArr.push(cEdges);
        }
        nodes = [];
        for (let edges of edgesArr) {
          for (let edge of edges) {
            if (allEdges.includes(edge)) continue;
            allEdges.push(edge);
            nodes.push(edge.getSource());
          }
        }
        edgesArr = [];
      }

      allEdges.forEach((edge) =>
        this.xGraph.setItemState(edge, "running", true)
      );
    },
    toggleEdgeType() {
      const edgeTypes = [
        "line",
        "polyline",
        "arc",
        "quadratic",
        "cubic",
        "cubic-vertical",
        "cubic-horizontal",
        "loop",
      ];
      const currentEdgeType = this.graphEdges[0]?.type.match();
      const allData = this.xGraph.save();
      const currentEdgeType1 = allData.edges[0].type.match(/custom:(.+)/)[1];
      const nextType =
        edgeTypes[
          (edgeTypes.findIndex((v) => v === currentEdgeType1) + 1) %
            edgeTypes.length
        ];

      this.xGraph.read({
        ...allData,
        edges: allData.edges.map((v) => {
          return {
            ...v,
            type: "custom:" + nextType,
          };
        }),
      });
      console.log(currentEdgeType, currentEdgeType1, nextType);
    },
  },
};
</script>

