  }
  .layout-button {
    background: white;
    position: absolute;
    right: 24px;
    top: 20px;
    padding: 6px;
    display: flex;
    gap: 6px;
    .button {
      background: white;
      box-shadow: none;
      width: 33px;
      height: 33px;
    }
