<template>
  <div class="nodes-preview">
    <div class="caption">执行节点</div>
    <div class="node-container">
      <div
        v-for="(nodesConfig, index) of cNodesList"
        :key="index"
        class="node-list"
      >
        <div
          v-if="nodesConfig[0] && nodesConfig[0] !== 'undefined'"
          class="title"
        >
          {{ nodesConfig[0] }}
        </div>
        <node
          v-for="(node, index2) in nodesConfig[1]"
          :key="index2"
          :node="node"
        />
      </div>
    </div>
  </div>
</template>

<script>
import Node from "./node.vue";
import _ from "lodash";

export default {
  name: "NodesPreview",
  components: {
    Node,
  },
  props: {
    nodeList: {
      type: Array,
      default: () => [],
    },
  },

  data() {
    return {};
  },
  computed: {
    cNodesList() {
      return _.entries(_.groupBy(this.nodeList, (v) => v.group));
    },
  },
  methods: {},
};
</script>

