<!-- 小窗口 -->

<template>
  <div class="tool">
    <!-- <div class="minimap-button" @click="handleToggle">
      {{ minimapVisible ? "⬆" : "⬇" }}
    </div> -->
    <div ref="minimap" class="minimap-container">
      <div id="minimap" class="minimap"></div>
    </div>
    <!-- <div class="zoom-tool">
      <button class="button" :disabled="zoom <= 10" @click="zoomOut">➖</button>
      <div class="zoom">{{ zoom }}%</div>
      <button class="button" :disabled="zoom >= 200" @click="zoomIn">➕</button>
      <div class="gap"></div>
      <button class="button" @click="zoomReset">⌖</button>
      <button class="button" @click="focusStart(NODE_TYPE.START.id)">🔘</button>
    </div> -->
  </div>
</template>

<script>
import _ from "lodash";

export default {
  name: "CanvasZoom",
  components: {},
  props: {
    graph: {
      type: Object,
      default: null,
    },
  },
  data() {
    return {
      zoom: 100,
      zoomRate: 10,
      minimapVisible: true, // 缩略图是否可见
    };
  },
  computed: {
    debounceFocusStart() {
      return _.debounce(this.focusStart, 650);
    },
  },
  watch: {
    graph(value) {
      if (value) {
        // 初始化完成了再注册
        // 滚轮缩放
        this.zoom = Math.round(this.graph.getZoom() * 100);
        this.graph.on("viewportchange", (e) => {
          if (e.action === "zoom") {
            this.zoom = _.ceil(this.graph.getZoom() * 100, 0);
          }
        });
      }
    },
    minimapVisible(v) {
      this.$refs.minimap.style.height = v ? "auto" : "0";
    },
  },

  methods: {
    handleToggle() {
      this.minimapVisible = !this.minimapVisible;
    },
    changeGraphZoom(value) {
      this.graph.zoomTo(value / 100, false, false);
    },
    zoomIn() {
      const zoomExpTo = _.chain(this.zoom)
        .divide(this.zoomRate)
        .ceil(0)
        .add(1)
        .multiply(this.zoomRate)
        .value();
      this.zoom = zoomExpTo > 200 ? 200 : zoomExpTo;
      this.changeGraphZoom(this.zoom);
    },
    zoomOut() {
      const zoomExpTo = _.chain(this.zoom)
        .divide(this.zoomRate)
        .floor(0)
        .subtract(1)
        .multiply(this.zoomRate)
        .value();
      this.zoom = zoomExpTo < 10 ? 10 : zoomExpTo;
      this.changeGraphZoom(this.zoom);
    },
    zoomReset() {
      this.zoom = 100;
      this.changeGraphZoom(this.zoom);
      this.debounceFocusStart();
    },
    focusStart(id = "START") {
      const startNode = this.graph.findById(id);
      if (startNode) {
        this.graph.focusItem(startNode, false);
      }
    },
  },
};
</script>

